// src/readme.ts
var replaceSection = (readme, marker, content) => {
  if (marker.trim().length === 0) {
    throw new Error("marker must not be empty");
  }
  const startMarker = `<!-- ${marker}:START -->`;
  const endMarker = `<!-- ${marker}:END -->`;
  if (!(readme.split(startMarker).length === 2) || !(readme.split(endMarker).length === 2)) {
    throw new Error("marker must exist only once in README");
  }
  if (readme.indexOf(startMarker) >= readme.indexOf(endMarker)) {
    throw new Error("start marker must appear before end marker");
  }
  const newReadme = readme.split(startMarker)[0] + `${startMarker}
${content}
${endMarker}` + readme.split(endMarker)[1];
  return newReadme;
};

// src/render.ts
var escapeMarkdownText = (text) => {
  return text.replace(/\r\n?|\n/g, " ").replace(/([\\`*_{}[\]()#+\-.!<>&~|])/g, "\\$1").trim();
};
var renderShelf = (shelf, showRating = false) => {
  if (shelf.length === 0) {
    return "Shelf is empty";
  }
  const lines = [];
  shelf.forEach((book) => {
    const title = escapeMarkdownText(book.title);
    const authorName = escapeMarkdownText(book.author_name);
    const roundedRating = Math.floor(book.user_rating);
    const stars = showRating && book.user_rating !== 0 ? "\u2605".repeat(roundedRating) + "\u2606".repeat(5 - roundedRating) + ` (${book.user_rating}/5)` : "";
    lines.push(
      `- [${title}](https://www.goodreads.com/book/show/${book.book_id}), ${authorName} ${stars}`.trim()
    );
  });
  return lines.join("\n");
};

// src/update.ts
var updateReadme = async (params) => {
  const actionConfig = parseInputs(params);
  const { goodreadsId, shelf, readmePath, marker, sort, ratings, limit } = actionConfig;
  const readmeFilePath = import_path.default.resolve(process.cwd(), readmePath);
  const readmeData = import_fs2.default.readFileSync(readmeFilePath, "utf-8");
  const fetched = await fetchShelf(goodreadsId, shelf);
  const parsed = parseXml2(fetched);
  const ordered = orderShelf(parsed, sort, limit);
  const rendered = renderShelf(ordered, ratings);
  const replaced = replaceSection(readmeData, marker, rendered);
  if (replaced === readmeData) {
    return {
      hasChanged: false,
      bookCount: ordered.length
    };
  }
  import_fs2.default.writeFileSync(readmeFilePath, replaced);
  return {
    hasChanged: true,
    bookCount: ordered.length
  };
};

// src/action.ts
var run = async () => {
  try {
    const goodreadsId = getInput("goodreads-user-id", { required: true });
    const shelf = getInput("shelf");
    const readmePath = getInput("readme-path");
    const marker = getInput("section");
    const sort = getInput("sort");
    const ratings = getInput("show-rating");
    const limit = getInput("max-books");
    const { hasChanged, bookCount } = await updateReadme({
      goodreadsId,
      shelf,
      readmePath,
      marker,
      sort,
      ratings,
      limit
    });
    setOutput("changed", hasChanged);
    setOutput("book-count", bookCount);
    const updateMessage = hasChanged ? "README updated" : "README already up to date";
    const booksRenderedMessage = bookCount === 0 ? "the shelf is empty" : `${bookCount} book(s) rendered`;
    await summary.addHeading("Goodreads README update").addRaw(`${updateMessage}: ${booksRenderedMessage}.`, true).write();
  } catch (err) {
    if (err instanceof Error) {
      setFailed(`Action failed with error ${err.message}`);
    } else {
      setFailed(`Action failed with error ${String(err)}`);
    }
  }
};

